import React, { useState, useEffect } from 'react';
import { C, slides } from '../data';

export default function Hero() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setCurrent((c) => (c + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, []);

  const prev = () => setCurrent((c) => (c - 1 + slides.length) % slides.length);
  const next = () => setCurrent((c) => (c + 1) % slides.length);
  const slide = slides[current];

  return (
    <section 
      id="hero" 
      style={{ 
        position: 'relative',
        minHeight: '100vh', 
        display: 'flex', 
        alignItems: 'center', 
        overflow: 'hidden',
        color: '#fff'
      }}
    >
      {/* --- Dynamic Background Image --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        backgroundImage: `url(${slide.imageUrl})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        transition: 'all 1.2s ease-in-out',
        zIndex: -2,
        transform: 'scale(1.05)', // Halka sa zoom depth ke liye
      }} />

      {/* --- Professional Overlay (Gradient for Readability) --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: 'linear-gradient(90deg, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.4) 50%, rgba(0,0,0,0.7) 100%)',
        zIndex: -1
      }} />

      {/* --- Decorative Grid --- */}
      <div style={{ position: 'absolute', inset: 0, opacity: 0.1, backgroundImage: `linear-gradient(${C.goldLight} 1px, transparent 1px), linear-gradient(90deg, ${C.goldLight} 1px, transparent 1px)`, backgroundSize: '50px 50px', zIndex: -1 }} />

      <div style={{ maxWidth: 1280, margin: '0 auto', padding: '80px 24px', width: '100%', position: 'relative' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 60 }}>

          {/* --- Text Content Section --- */}
          <div style={{ 
            flex: 1, 
            minWidth: 320, 
            padding: '40px', 
            borderRadius: '24px',
            background: 'rgba(255, 255, 255, 0.03)',
            backdropFilter: 'blur(10px)',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)'
          }}>
            <div style={{ 
              display: 'inline-flex', 
              alignItems: 'center',
              gap: '8px',
              padding: '8px 16px', 
              borderRadius: 99, 
              fontSize: 12, 
              fontWeight: 700, 
              textTransform: 'uppercase', 
              letterSpacing: '0.2em', 
              marginBottom: 24, 
              background: `linear-gradient(90deg, ${C.gold}, ${C.goldLight})`, 
              color: '#000' 
            }}>
              <span style={{ fontSize: '14px' }}>✦</span> {slide.tag}
            </div>

            <h1 style={{ 
              fontSize: 'clamp(2.5rem, 6vw, 4rem)', 
              fontWeight: 900, 
              fontFamily: "'Playfair Display', serif", 
              lineHeight: 1.1, 
              marginBottom: 24,
              letterSpacing: '-0.02em'
            }}>
              {slide.title}
            </h1>

            <p style={{ 
              fontSize: '1.1rem', 
              color: 'rgba(255,255,255,0.8)', 
              marginBottom: 40, 
              lineHeight: 1.8, 
              maxWidth: 550,
              fontWeight: 400
            }}>
              {slide.subtitle}
            </p>

            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 20 }}>
              <button
                onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
                style={{ 
                  padding: '16px 40px', 
                  borderRadius: 12, 
                  fontWeight: 800, 
                  fontSize: 15, 
                  background: C.gold, 
                  color: '#000', 
                  border: 'none', 
                  cursor: 'pointer', 
                  boxShadow: `0 10px 30px ${C.gold}66`,
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-3px)'}
                onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
              >
                Get Started Now
              </button>
              <button
                onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
                style={{ 
                  padding: '16px 40px', 
                  borderRadius: 12, 
                  fontWeight: 700, 
                  fontSize: 15, 
                  background: 'transparent', 
                  color: '#fff', 
                  border: '2px solid rgba(255,255,255,0.3)', 
                  cursor: 'pointer', 
                  backdropFilter: 'blur(5px)',
                  transition: 'all 0.3s'
                }}
                onMouseEnter={e => e.currentTarget.style.borderColor = C.gold}
                onMouseLeave={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.3)'}
              >
                View Courses
              </button>
            </div>
          </div>

          {/* --- Floating Mini-Card (Right Side) --- */}
          <div style={{ flex: 1, display: 'flex', justifyContent: 'center' }}>
            <div style={{
              position: 'relative',
              width: '280px',
              padding: '30px',
              background: 'rgba(255,255,255,0.1)',
              borderRadius: '30px',
              backdropFilter: 'blur(20px)',
              border: '1px solid rgba(255,255,255,0.2)',
              textAlign: 'center',
              animation: 'float 5s ease-in-out infinite'
            }}>
              <div style={{ fontSize: '40px', marginBottom: '15px' }}>🏆</div>
              <h3 style={{ color: C.gold, marginBottom: '5px' }}>Top Rated</h3>
              <p style={{ fontSize: '13px', opacity: 0.8 }}>Trusted by 10,000+ students worldwide</p>
            </div>
          </div>
        </div>

        {/* --- Modern Navigation Controls --- */}
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          marginTop: 80,
          paddingTop: 30,
          borderTop: '1px solid rgba(255,255,255,0.1)'
        }}>
          <div style={{ display: 'flex', gap: 12 }}>
            {slides.map((_, i) => (
              <div 
                key={i} 
                onClick={() => setCurrent(i)}
                style={{ 
                  width: i === current ? 40 : 12, 
                  height: 6, 
                  borderRadius: 3, 
                  background: i === current ? C.gold : 'rgba(255,255,255,0.2)', 
                  cursor: 'pointer',
                  transition: 'all 0.4s' 
                }} 
              />
            ))}
          </div>
          <div style={{ display: 'flex', gap: 15 }}>
             <button onClick={prev} style={navButtonStyle}>←</button>
             <button onClick={next} style={navButtonStyle}>→</button>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(2deg); }
        }
      `}</style>
    </section>
  );
}

const navButtonStyle = {
  width: 50, 
  height: 50, 
  borderRadius: '50%', 
  background: 'rgba(255,255,255,0.05)', 
  border: '1px solid rgba(255,255,255,0.1)', 
  color: '#fff', 
  cursor: 'pointer', 
  fontSize: '20px',
  transition: 'all 0.3s'
};
